export const GRADE1_ALL_WORDS: Array<Grade1Word & { unit: number; unitTitleVi: string; phonicsLetter: string }> = GRADE1_UNITS.flatMap(
  (u) => u.words.map((w) => ({ ...w, unit: u.unit, unitTitleVi: u.titleVi, phonicsLetter: u.phonicsLetter })),
);

export function getGrade1Unit(unitNumber: number): Grade1Unit {
  return GRADE1_UNITS.find((u) => u.unit === unitNumber) ?? GRADE1_UNITS[0];
}
